const config = $('Merge Context').item.json;
const busyEvents = items.map(i => i.json).filter(e => e && (e.start || e.end));
const args = config.toolArgs;

const slotMinutes = config.bookingSlotDurationMinutes || 30;
const [startH, startM] = (config.businessHoursStart || '09:00').split(':').map(Number);
const [endH, endM] = (config.businessHoursEnd || '17:00').split(':').map(Number);

const dayStart = new Date(`${args.date}T00:00:00`);
dayStart.setHours(startH, startM, 0, 0);
const dayEnd = new Date(`${args.date}T00:00:00`);
dayEnd.setHours(endH, endM, 0, 0);

const busyRanges = busyEvents.map(e => ({
  start: new Date(e.start?.dateTime || e.start?.date),
  end: new Date(e.end?.dateTime || e.end?.date),
}));

const slots = [];
for (let t = new Date(dayStart); t < dayEnd; t = new Date(t.getTime() + slotMinutes * 60000)) {
  const slotEnd = new Date(t.getTime() + slotMinutes * 60000);
  const overlaps = busyRanges.some(b => t < b.end && slotEnd > b.start);
  if (!overlaps) {
    slots.push(t.toTimeString().slice(0, 5));
  }
}

const preferredTime = args.preferredTime;
const preferredAvailable = preferredTime ? slots.includes(preferredTime) : false;

return [{
  json: {
    date: args.date,
    preferredTime: preferredTime || null,
    preferredAvailable,
    alternativeSlots: slots.filter(s => s !== preferredTime).slice(0, 5),
    allAvailableSlots: slots,
  }
}];

const config = $('Merge Context').item.json;
const args = config.toolArgs;
const serviceMenu = config.serviceMenu || [];
const match = serviceMenu.find(s => (s.name || '').toLowerCase() === (args.service || '').toLowerCase());
const durationMinutes = (match && match.durationMinutes) || config.bookingSlotDurationMinutes || 30;

const [h, m] = args.time.split(':').map(Number);
const totalMinutes = h * 60 + m + durationMinutes;
const endH = String(Math.floor((totalMinutes / 60) % 24)).padStart(2, '0');
const endM = String(totalMinutes % 60).padStart(2, '0');

return [{ json: { endTime: `${endH}:${endM}` } }];

