const config = $('Merge Context').item.json;
const quoteConfig = config.quoteConfig || {};
const jobTypes = quoteConfig.jobTypes || [];
const args = config.toolArgs || {};
const description = String(args.jobDescription || '').toLowerCase();

function scoreJobType(job) {
  const keywords = job.keywords || [];
  return keywords.filter(k => description.includes(String(k).toLowerCase())).length;
}

let best = null;
let bestScore = 0;
for (const job of jobTypes) {
  const score = scoreJobType(job);
  if (score > bestScore) {
    best = job;
    bestScore = score;
  }
}

// Trusts the caller/AI-supplied isEmergency flag only (see requirement 3's input contract and the sticky note above for why a server-side clock check was tried and dropped).
const isEmergencyApplied = args.isEmergency === true;

if (!best || bestScore === 0) {
  return [{ json: { ...config, matched: false, isEmergencyApplied, jobDescription: args.jobDescription || '' } }];
}

const multiplier = isEmergencyApplied ? (quoteConfig.emergencyMultiplier || 1) : 1;
const priceMin = Math.round((best.priceMin || 0) * multiplier);
const priceMax = Math.round((best.priceMax ?? best.priceMin ?? 0) * multiplier);

return [{ json: {
  ...config,
  matched: true,
  matchedJobType: best.name,
  priceMin,
  priceMax,
  calloutFee: quoteConfig.calloutFee || 0,
  calloutFeeWaivedIfBooked: !!quoteConfig.calloutFeeWaivedIfBooked,
  isEmergencyApplied,
  emergencyMultiplier: quoteConfig.emergencyMultiplier || 1,
  materialsNote: best.materialsNote || null,
  jobDescription: args.jobDescription || '',
} }];

const d = $json;
const parts = [];
const priceText = d.priceMin === d.priceMax ? `£${d.priceMin}` : `£${d.priceMin} to £${d.priceMax}`;
parts.push(`For ${d.matchedJobType.toLowerCase()}, our standard price is ${priceText}.`);
if (d.calloutFee > 0) {
  parts.push(`There's also a £${d.calloutFee} callout fee${d.calloutFeeWaivedIfBooked ? ', which is waived if you book the appointment with us today' : ''}.`);
}
if (d.isEmergencyApplied) {
  parts.push('As this is outside our normal hours, an out-of-hours charge is already included in that price.');
}
if (d.materialsNote) {
  parts.push(d.materialsNote);
}
parts.push('Would you like me to book that in for you?');

return [{ json: { ...d, resultText: parts.join(' '), wasFallback: false } }];

